struct MouseTracker<Content: View>: View {
    @State private var x = 0.0
    @ViewBuilder var content: (CGPoint) -> Content   // caller decides the markup

    var body: some View {
        content(CGPoint(x: x, y: 0))
            .onContinuousHover { phase in
                if case let .active(p) = phase { x = p.x }
            }
    }
}
