let registration = UICollectionView.CellRegistration<UICollectionViewListCell, Int> { cell, _, item in
    var content = cell.defaultContentConfiguration()
    content.text = "\(item)"                    // caller decides the cell content
    cell.contentConfiguration = content
}
dataSource = UICollectionViewDiffableDataSource<Section, Int>(collectionView: view) { cv, indexPath, item in
    cv.dequeueConfiguredReusableCell(using: registration, for: indexPath, item: item)
}
